INSERT INTO personalized_products (id, slug, name, category, price, electronic_price, short_description, cover_image_url, publisher_id, owner_type) VALUES
('prod-custom-1', 'custom-story-book', 'القصة المخصصة', 'custom', 19500, 11970, 'قصة فريدة بطلها طفلك، باسمه وصورته وهواياته.', 'https://picsum.photos/seed/custom1/600/800', NULL, 'platform'),
('prod-custom-2', 'emotional-story', 'القصة الشعورية', 'custom', 21000, 13500, 'قصة مخصصة لمساعدة طفلك على فهم مشاعره والتعبير عنها.', 'https://picsum.photos/seed/custom2/600/800', NULL, 'platform'),
('prod-custom-3', 'deep-sea-adventures', 'اعماق البحار', 'custom', 6000, 600, 'مغامرات شيقة بطلها طفلك في أعماق البحار المحيطات.', 'https://picsum.photos/seed/custom3/600/800', NULL, 'platform'),
('prod-lib-1', 'prophets-stories', 'قصص الأنبياء للأطفال', 'library', 350, 150, 'مجموعة مختارة من قصص الأنبياء بأسلوب مبسط ومناسب للأطفال، مع رسومات توضيحية جميلة (بدون تجسيد).', 'https://picsum.photos/seed/lib1/600/800', 'pub-1', 'publisher'),
('prod-lib-2', 'little-explorer', 'موسوعة المستكشف الصغير', 'library', 400, NULL, 'رحلة في عالم العلوم، الفضاء، جسم الإنسان، والطبيعة. مليئة بالحقائق المدهشة والصور.', 'https://picsum.photos/seed/lib2/600/800', 'pub-2', 'publisher'),
('prod-lib-3', 'morals-garden', 'حديقة الأخلاق', 'library', 300, 120, 'قصص قصيرة تعلم الأطفال الآداب الإسلامية والأخلاق الحميدة في التعامل مع الأسرة والجيران والأصدقاء.', 'https://picsum.photos/seed/lib3/600/800', 'pub-1', 'publisher'),
('prod-lib-4', 'bedtime-stories', 'حكايات قبل النوم', 'library', 320, 130, 'مجموعة هادئة ولطيفة من القصص الخيالية القصيرة لتساعد طفلك على الاسترخاء والنوم بأحلام سعيدة.', 'https://picsum.photos/seed/lib4/600/800', 'pub-2', 'publisher')
INSERT INTO creative_writing_packages (id, slug, name, age_group, price, duration_text, sessions_count, session_duration, target_audience, prerequisite_note, short_description, full_description, is_active) VALUES
('pkg-1', 'golden-words', 'الكلمات الذهبية', 'under_12', 2990, '3 أشهر', 12, '40 دقيقة', 'تناسب الطفل الذي يخوض تجربة منظمة أولى مع الكتابة، أو يريد اكتشاف علاقته بها في مساحة فردية دافئة وخفيفة، دون الحاجة إلى خبرة سابقة.', 'مستقلة بذاتها (يمكن الانتقال بعدها إلى السطور السحرية لكنها ليست شرطًا لها)', 'رحلة استكشافية قصيرة للمبتدئين.', 'دورة تركز على اكتشاف الكتابة كمساحة للتعبير...', true),
('pkg-2', 'magic-lines', 'السطور السحرية', 'under_12', 5990, '6 أشهر', 24, NULL, 'تناسب الطفل الذي يريد مساحة أطول للكتابة والتجريب، ويرغب في توسيع أدواته واكتشاف أنواع متعددة من الكتابة والعمل على مشروع كتابي خاص يمتد عبر فترة أطول.', 'لا تشترط إتمام الكلمات الذهبية مسبقًا', 'رحلة أطول لتوسيع أدوات الكتابة وبناء مشروع.', 'دورة لتوسيع مهارات الكتابة وبناء مشروع شخصي...', true),
('pkg-3', 'first-spark', 'الشرارة الأولى', '12_plus', 2990, '3 أشهر', 12, '40 دقيقة', 'تناسب اليافع أو الشاب أو الكبير الذي يريد أن يبدأ ممارسة الكتابة، أو يكتشف علاقته بها، أو يحوّل أفكاره الأولى إلى نصوص فعلية، دون الحاجة إلى الاشتراك في مسار طويل.', 'مستقلة بذاتها', 'رحلة قصيرة لتحويل الأفكار إلى نصوص.', 'الخطوة الأولى في عالم الكتابة والتعبير...', true),
('pkg-4', 'crafting-impact', 'صياغة الأثر', '12_plus', 5990, '6 أشهر', 24, NULL, 'تناسب من يريد أن يمنح الكتابة وقتًا أطول، ويعمّق أدواته، ويجرب أكبر من نوع أدبي، ثم ينتقل إلى بناء مشروع كتابي خاص به.', 'مستقلة بذاتها، ويمكن الاشتراك فيها مباشرة', 'مسار متعمق لتجربة أنواع أدبية مختلفة.', 'برنامج متكامل يعمق أدوات الكاتب ويوسع مداركه...', true),
('pkg-5', 'story-maker', 'صانع الحكاية', '12_plus', 11990, '6 أشهر', 24, NULL, 'تناسب المشارك الذي أتم «صياغة الأثر» وأصبح لديه أساس كتابي ومشروع يمكن تطويره، ويريد التعمق في بناء الحكاية والعمل على مشروع أدبي أكبر امتدادًا.', 'يشترط إتمام رحلة صياغة الأثر أولًا', 'رحلة لبناء وتطوير مشروع أدبي متكامل.', 'التعمق في بناء الحكاية والشخصيات وتطوير مشروع أدبي متماسك...', true),
('pkg-6', 'journey-to-story', 'رحلتي نحو الحكاية', '12_plus', 19190, '12 شهر (البرنامج الكامل)', 48, NULL, 'تناسب من يريد خوض مسار سنوي واحد متصل بدلًا من رحلتين منفصلتين، ويبحث عن تجربة متصلة تمنحه الوقت للانتقال من التأسيس والتجريب إلى بناء المشروع ثم صقله وتطوير ملف أعماله.', 'لا تشترط إتمام أي رحلة سابقة، لأنها تحتوي المسار الكامل داخل تجربة سنوية واحدة', 'المسار الكامل من التجريب إلى صقل مشروع التخرج.', 'برنامج سنوي شامل ينتقل بالكاتب من نقطة البداية وحتى إنهاء مشروعه...', true)
